#!/usr/bin/env python3
from pathlib import Path
import sys,base64,zlib
root=Path(sys.argv[1] if len(sys.argv)>1 else "upstream")
cpp=zlib.decompress(base64.b64decode("")).decode("utf-8")
(root/"addonProfilerLite.cpp").write_text(cpp,encoding="utf-8",newline="\n")
print("AddonProfiler B1R4 Calibrated applied")
